async function retry<T>(fn: () => Promise<T>, times = 3, delay = 500): Promise<T> {
  for (let i = 0; i < times; i++) {
    try { return await fn(); } catch (e) {
      if (i === times - 1) throw e;
      await new Promise(r => setTimeout(r, delay * 2 ** i));
    }
  }
  throw new Error('unreachable');
}

type Events = { message: string; error: Error; close: void };
type Listener<T> = T extends void ? () => void : (v: T) => void;
class TypedEmitter<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Set<Function>>();
  on<K extends keyof E>(event: K, cb: Listener<E[K]>) {
    (this.listeners.get(event) ?? this.listeners.set(event, new Set()).get(event)!).add(cb);
  }
  emit<K extends keyof E>(event: K, ...args: E[K] extends void ? [] : [E[K]]) {
    this.listeners.get(event)?.forEach(cb => cb(...args));
  }
}

