fn sieve(n: usize) -> Vec<usize> {
    let mut is_prime = vec![true; n+1];
    is_prime[0] = false; if n > 0 { is_prime[1] = false; }
    let mut i = 2;
    while i * i <= n {
        if is_prime[i] { (i*i..=n).step_by(i).for_each(|j| is_prime[j] = false); }
        i += 1;
    }
    (0..=n).filter(|&i| is_prime[i]).collect()
}

